#include <cuda_runtime.h>
#include "../metropolis-cuda/utils.h"
#include "../metropolis-cuda/kernel_prng.h"
#include "corrected_native_kernel_metropolis.h"
#include <vector>
#include <string>
#include <cstring>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s:%d %s\n",__FILE__,__LINE__,cudaGetErrorString(e));exit(2);}}while(0)
std::vector<double>rd(const char*n){FILE*f=fopen(n,"rb");fseek(f,0,SEEK_END);size_t z=ftell(f)/8;rewind(f);std::vector<double>a(z);if(fread(a.data(),8,z,f)!=z)abort();fclose(f);return a;}
struct Arr{bool wide;size_t n;void*d;std::vector<int32_t>hi;std::vector<uint64_t>hu;};
std::vector<double> readarr(Arr&a){std::vector<double>v;if(a.wide){std::vector<uint64_t>x(a.n+16);CK(cudaMemcpy(x.data(),a.d,x.size()*8,cudaMemcpyDeviceToHost));for(auto t:x){v.push_back(uint32_t(t));v.push_back(uint32_t(t>>32));}}else{std::vector<int32_t>x(a.n+16);CK(cudaMemcpy(x.data(),a.d,x.size()*4,cudaMemcpyDeviceToHost));v.assign(x.begin(),x.end());}return v;}
void reset(Arr&a){CK(cudaMemcpy(a.d,a.wide?(void*)a.hu.data():(void*)a.hi.data(),(a.n+16)*(a.wide?8:4),cudaMemcpyHostToDevice));}
struct Case{float h,B;int ns;std::vector<Arr>as;};
void launch(Case&c){for(int i=0;i<c.ns;i++)for(int alt=0;alt<2;alt++){kernel_metropolis<<<dim3(2,2,8),dim3(16,4,4)>>>(32768,32,(int*)c.as[0].d+8,(int*)c.as[1].d+8,c.h,c.B,(uint64_t*)c.as[2].d+8,(uint64_t*)c.as[3].d+8,alt);CK(cudaGetLastError());CK(cudaDeviceSynchronize());}}
int main(){auto pre=rd(FIXTURE),gold=rd(ORACLE);size_t pos=1;std::vector<Case>cs;for(int ci=0;ci<(int)pre[0];ci++){if(pre[pos++]!=32)abort();Case c;c.h=pre[pos++];c.B=pre[pos++];c.ns=pre[pos++];for(int i=0;i<4;i++){Arr a;a.wide=i>=2;a.n=a.wide?8192:32768;if(a.wide){a.hu.assign(a.n+16,0x5a5a5a5a5a5a5a5aULL);for(size_t j=0;j<a.n;j++){uint64_t lo=pre[pos++],hi=pre[pos++];a.hu[j+8]=lo|(hi<<32);}}else{a.hi.assign(a.n+16,-12345);for(size_t j=0;j<a.n;j++)a.hi[j+8]=pre[pos++];}CK(cudaMalloc(&a.d,(a.n+16)*(a.wide?8:4)));reset(a);c.as.push_back(a);}cs.push_back(c);}if(pos!=pre.size())abort();for(auto&c:cs)launch(c);
for(int trial=1;trial<=5;trial++){auto art=pre;size_t go=0;bool ok=true;std::vector<double>times;double total=0;for(auto&c:cs){std::vector<std::vector<double>>before;for(auto&a:c.as){reset(a);before.push_back(readarr(a));}CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();launch(c);double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();times.push_back(dt);total+=dt;std::vector<std::vector<double>>after;for(auto&a:c.as)after.push_back(readarr(a));for(auto group:{after,before})for(auto&v:group)for(auto x:v){ok&=go<gold.size()&&x==gold[go];go++;art.push_back(x);}}if(go!=gold.size())abort();std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"sum3_complete_corrected_Ising_Metropolis_sweep_components\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,total,ok?"true":"false",go,path.c_str(),art.size());for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("]}\n");}}
